//!
//! The pixels are in flash deflated, and only there: [`unpack`] inflates them into a
//! buffer the game borrows for as long as it runs, and every [`Sprite`] is a place in
//! that buffer. Sizes are constants, so the layout is settled at compile time.

/// A sprite: one byte per pixel into [`PALETTE`]; [`TRANSPARENT`] shows through.
///
/// Stored as its distinct rows, each once, and which of them each row of the picture is:
/// the scenery repeats rows far more than it has new ones. Both live in the unpacked
/// [`Art`], at the offsets here.
pub struct Sprite {
    pub width: u16,
    pub height: u16,
    /// Where the `height`-byte row map starts: for each row, which distinct row it is.
    rows: u16,
    /// Where the distinct rows start, `width` bytes each, in the order first used.
    pixels: u16,
}

impl Sprite {
    /// The palette index at `(x, y)`, [`TRANSPARENT`] included, or `None` outside.
    #[inline(always)]
    pub fn index(&self, art: &Art<'_>, x: usize, y: usize) -> Option<u8> {
        if x >= self.width as usize || y >= self.height as usize {
            return None;
        }
        let row = *art.0.get(self.rows as usize + y)? as usize;
        art.0
            .get(self.pixels as usize + row * self.width as usize + x)
            .copied()
    }

    /// The RGB565 colour at `(x, y)`, or `None` where it is transparent or outside.
    #[inline(always)]
    pub fn at(&self, art: &Art<'_>, x: usize, y: usize) -> Option<u16> {
        match self.index(art, x, y)? {
            TRANSPARENT => None,
            i => PALETTE.get(i as usize).copied(),
        }
    }
}

/// The sprites' pixels, unpacked: made only by [`unpack`], so a sprite is never read
/// from a buffer that is short or holds anything else.
pub struct Art<'a>(&'a [u8]);

/// Bytes [`unpack`] needs to inflate into.
pub const UNPACKED_LEN: usize = 14525;

/// Inflate the sprites into `buf`, which must be at least [`UNPACKED_LEN`] bytes.
///
/// A stream that comes out any other length than the one baked is refused rather than
/// drawn: that is flash that is not what was built.
pub fn unpack(buf: &mut [u8]) -> Result<Art<'_>, compcol::embed::flate::Error> {
    let buf = buf
        .get_mut(..UNPACKED_LEN)
        .ok_or(compcol::embed::flate::Error::OutputFull)?;
    let n = compcol::embed::flate::inflate(&PACKED[..], compcol::embed::flate::Buffer::new(buf))?;
    if n != UNPACKED_LEN as u64 {
        return Err(compcol::embed::flate::Error::OutputFull);
    }
    Ok(Art(buf))
}

